AddCSLuaFile()ENT.Type="anim"ENT.Base="base_anim"ENT.Author="Paloma"ENT.Category="Pointshop Entities"ENT.PrintName="Shockwave"ENT.Spawnable = false ENT.AdminOnly=false function ENT.Initialize(C)C:SetModel("models/hunter/plates/plate.mdl")C:SetMaterial("models/effects/intro_tearshape")C:SetColor(Color(255,255,255,255))C:SetRenderMode(RENDERMODE_TRANSCOLOR)C:SetMoveType(MOVETYPE_NONE)C:SetSolid(SOLID_NONE)C:SetCollisionGroup(COLLISION_GROUP_IN_VEHICLE)C.SpawnTime=CurTime()C.LifeTime=.25 timer.Simple(C.LifeTime,function()if IsValid(C)then if SERVER then C:Remove()end end end)end if CLIENT then local C=Material("sprites/heatwave")function ENT.Draw(w)local S=CurTime()-(w.SpawnTime or 0)local Y=math.Clamp(S/(w.LifeTime or.25),0,1)local E=Lerp(Y,10,2000)render.SetMaterial(C)render.DrawSprite(w:GetPos(),E,E,Color(255,255,255,255))end end
